// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testRegression_property() public {
        c.XBornID();


        c = new XBORNID();
        c.XBornID();






        c = new XBORNID();
        c.XBornID();

        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.getTokens();

        bool ok;
        vm.prank(alice);
        try c.getTokens() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false, "Reference should revert, buggy should not");
    }
}
